449	// CloseShift 结束班次。任一接班交接存在未确认接收的事项（待处理、退回、
450	// 处理结果缺失或无法识别）时不允许结束，其他交接已完成也不能放行；空清单
451	// 交接视为已完成，可以结束。
452	// 结束成功时把在班事项（本班新增与已接收，含结束前已关闭者）冻结为结束时记录；
453	// 校验或保存失败时不留下任何记录，班次保持进行中，也不改变交接结果、
454	// 事项归属与已保存的处理经过。
455	func (svc *Service) CloseShift(shiftID string) (Shift, error) {
456		shiftID = clean(shiftID)
457		var result Shift
458		err := svc.store.mutate(func(d *Data) error {
459			sh, _ := findShift(d, shiftID)
460			if sh == nil {
461				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
462			}
463			if sh.Closed {
464				return fmt.Errorf("%w：班次 %s 已结束", ErrShiftClosed, sh.ID)
465			}
466			for i := range d.Handovers {
467				h := &d.Handovers[i]
468				if h.ToShiftID == sh.ID && !h.Completed() {
469					return fmt.Errorf("%w：接班交接 %s 仍有未确认接收的事项，班次不能结束",
470						ErrHandoverState, h.ID)
471				}
472			}
473			now := svc.now()
474			sh.Closed = true
475			sh.ClosedAt = &now
476	
477			// 冻结结束时在班的全部事项。退回或未确认的交接事项当前班次仍在交班
478			// 班次，不会被快照；结束前已关闭的事项保留关闭人与关闭时间。
479			record := &ShiftCloseRecord{Items: []CloseItemSnapshot{}}
480			for i := range d.Items {
481				it := &d.Items[i]
482				if it.CurrentShiftID != sh.ID {
483					continue
484				}
485				record.Items = append(record.Items, CloseItemSnapshot{
486					ItemID:        it.ID,
487					Content:       it.Content,
488					Severity:      it.Severity,
489					Constraints:   it.Constraints,
490					FollowOwner:   it.FollowOwner,
491					Closed:        it.Closed,
492					ClosedAt:      it.ClosedAt,
493					CloseOperator: it.CloseOperator,
494				})
495			}
496			sort.Slice(record.Items, func(i, j int) bool { return record.Items[i].ItemID < record.Items[j].ItemID })
497			sh.CloseRecord = record
498	
499			result = *sh
500			return nil
501		})
502		return result, err
503	}
