811	// ItemJourney 凭事项编号汇总它从建立到当前的处理经过：保留事项自身的
812	// 建立、修改、关闭记录，并加入它参与的各次交接（发起交接、逐轮退回、补充后
813	// 重新提交、确认接收或继续跟踪），无须先知道涉及哪些交接编号。
814	// 经过按实际发生时刻排序（带不同时区的时间按同一实际时刻比较）；同一时刻下
815	// 同一交接内保持发起、该轮退回、该轮重新提交、后续处理的先后，不同交接按
816	// 交接编号排列。同一次接收若已出现在事项历史里只展示一次：除操作人与实际
817	// 时刻相同外，还须接收说明明确记载的交接编号、交班、接班班次与接收方式都与
818	// 交接清单一致；任一记载不一致，或说明缺少明确记载（旧数据、没有对应交接
819	// 清单的接收历史）时，事项历史原样保留，不凭空补交接编号。只读查询，
820	// 不改变事项、交接进度或班次结束时记录。
821	func (svc *Service) ItemJourney(itemID string) (ItemJourney, error) {
822		itemID = clean(itemID)
823		d := &svc.store.data
824		it, _ := findItem(d, itemID)
825		if it == nil {
826			return ItemJourney{}, fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
827		}
828		j := ItemJourney{Item: *it}
829	
830		// 排序键：先按实际发生时刻（未记录时间的排最后），同一时刻下事项自身
831		// 事件在前，其后按交接编号分组，组内保持生成顺序（发起、逐轮退回、
832		// 该轮重新提交、后续处理）。
833		type keyedEvent struct {
834			ev    JourneyEvent
835			group string // "" 表示事项自身事件，否则为交接编号
836			ord   int    // 同一（时刻、分组）内的先后
837		}
838		var events []keyedEvent
839		seq := 0
840		add := func(ev JourneyEvent, group string) {
841			events = append(events, keyedEvent{ev: ev, group: group, ord: seq})
842			seq++
843		}
844	
845		// received 事件与交接清单中的接收处理确属同一次接收时只展示一次（以交接
846		// 事件展示，信息更全：交接编号、交班与接班班次、该次保存的处理结果、操作人、
847		// 时间，继续跟踪还含跟踪说明与当时的后续负责人）。是否同一次接收不能仅凭
848		// 同一操作人与同一实际时刻：接收说明中明确记载的交接编号、交班、接班班次或
849		// 接收方式与本次交接不一致时，两条记录各自保留；说明没有明确记载（旧数据、
850		// 无对应交接清单的接收历史）时同样不合并，缺少足够信息无法确认即原样展示，
851		// 不凭班次负责人、事项当前位置或当前处理结果猜测归属，也不凭空补交接编号。
852		receivedUsed := make([]bool, len(it.Events))
853	
854		hs := append([]Handover(nil), d.Handovers...)
855		sort.Slice(hs, func(i, k int) bool { return hs[i].ID < hs[k].ID })
856		for k := range hs {
857			h := &hs[k]
858			e, _ := findEntry(h, itemID)
859			if e == nil {
860				continue
861			}
862			j.HasHandovers = true
863			j.Results = append(j.Results, EntryView{
864				HandoverID: h.ID,
865				FromShift:  h.FromShiftID,
866				ToShift:    h.ToShiftID,
867				Entry:      *e,
868			})
869	
870			// 发起交接：交接记录本身不记操作人，明确显示未记录，不以班次负责人代替。
871			add(JourneyEvent{
872				At: h.CreatedAt, TimeKnown: !h.CreatedAt.IsZero(),
873				Kind: "handover-init", HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
874			}, h.ID)
875			for _, r := range e.Rounds {
876				add(JourneyEvent{
877					At: r.ReturnedAt, TimeKnown: !r.ReturnedAt.IsZero(),
878					Kind: "return", Operator: r.ReturnOperator,
879					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
880					RoundSeq: r.Seq, Reason: r.Reason,
881				}, h.ID)
882				if r.ResubmittedAt != nil {
883					add(JourneyEvent{
884						At: *r.ResubmittedAt, TimeKnown: !r.ResubmittedAt.IsZero(),
885						Kind: "resubmit", Operator: r.SupplementOperator,
886						HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
887						RoundSeq: r.Seq, Supplement: r.Supplement,
888						SupplementOperator: r.SupplementOperator, SupplementAt: r.SupplementAt,
889					}, h.ID)
890				}
891			}
892			if e.Status.Received() {
893				kind := "confirm"
894				if e.Status == EntryTracking {
895					kind = "track"
896				}
897				ev := JourneyEvent{
898					Kind: kind, Operator: e.Operator,
899					HandoverID: h.ID, FromShift: h.FromShiftID, ToShift: h.ToShiftID,
900					TrackingNote: e.TrackingNote,
901					// 继续跟踪当时指定的后续负责人取自交接记录快照，
902					// 之后修改事项负责人不改变这里的历史值。
903					FollowOwner: e.FollowOwner,
904				}
905				// 处理时间缺失或为旧数据零值时仍保留该处理事件，
906				// 时间标为未记录，排在有真实时间的事件之后。
907				if validProcessedAt(e.ProcessedAt) {
908					ev.At, ev.TimeKnown = *e.ProcessedAt, true
909				}
910				add(ev, h.ID)
911				if validProcessedAt(e.ProcessedAt) {
912					for i := range it.Events {
913						iev := &it.Events[i]
914						if iev.Kind != "received" || receivedUsed[i] {
915							continue
916						}
917						if !iev.At.Equal(*e.ProcessedAt) || iev.Operator != e.Operator {
918							continue
919						}
920						// 操作人与实际时刻相同只是前提；还要核对接收说明里明确记载的
921						// 交接编号、交班、接班班次与接收方式。只比较说明中明确记载的
922						// 字段（旧格式没有交接编号与交班班次）：记载与本次一致或未记载
923						// 才合并；明确不一致（交给另一个班次、方式不同、无对应交接
924						// 清单）时跳过这条，继续找真正同一次的记录——两条历史的存放
925						// 先后不能决定哪一条被隐藏。
926						attr, ok := parseReceivedDetail(iev.Detail)
927						if !ok {
928							continue
929						}
930						if (attr.handoverID != "" && attr.handoverID != h.ID) ||
931							(attr.fromShift != "" && attr.fromShift != h.FromShiftID) ||
932							(attr.toShift != "" && attr.toShift != h.ToShiftID) ||
933							(attr.kind != "" && attr.kind != kind) {
934							continue
935						}
936						receivedUsed[i] = true
937						break
938					}
939				}
940			}
941		}
942	
943		// 事项自身历史：建立、修改、关闭原样保留；未被交接接收事件覆盖的
944		// received 事件（旧数据）也保留。
945		for i, iev := range it.Events {
946			if iev.Kind == "received" && receivedUsed[i] {
947				continue
948			}
949			add(JourneyEvent{
950				At: iev.At, TimeKnown: !iev.At.IsZero(),
951				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
952			}, "")
953		}
954	
955		sort.SliceStable(events, func(i, k int) bool {
956			a, b := events[i], events[k]
957			if a.ev.TimeKnown != b.ev.TimeKnown {
958				return a.ev.TimeKnown
959			}
960			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
961				return a.ev.At.Before(b.ev.At)
962			}
963			if a.group != b.group {
964				return a.group < b.group
965			}
966			return a.ord < b.ord
967		})
968		for _, ke := range events {
969			j.Events = append(j.Events, ke.ev)
970		}
971		return j, nil
972	}
973	
974	// GetHandover 按编号查询交接。
975	func (svc *Service) GetHandover(id string) (Handover, error) {
976		h, _ := findHandover(&svc.store.data, clean(id))
977		if h == nil {
978			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
979		}
980		return *h, nil
981	}
982	
983	// ListHandovers 返回全部交接记录，按编号排序。
984	func (svc *Service) ListHandovers() []Handover {
985		out := append([]Handover(nil), svc.store.data.Handovers...)
986		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
987		return out
988	}
989	
990	// OverlapNotes 返回涉及指定班次的全部重叠说明。
991	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
992		shiftID = clean(shiftID)
993		out := []OverlapNote{}
994		for _, n := range svc.store.data.Notes {
995			if n.ShiftA == shiftID || n.ShiftB == shiftID {
996				out = append(out, n)
997			}
998		}
999		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
1000		return out
1001	}
1002	
1003	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
1004	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
1005	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
1006	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
1007		shiftID = clean(shiftID)
1008		d := &svc.store.data
1009		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
1010		sh, _ := findShift(d, shiftID)
1011		if sh == nil {
1012			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
1013		}
1014		rep.Shift = *sh
1015	
1016		for _, n := range d.Notes {
1017			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
1018				rep.OverlapNotes = append(rep.OverlapNotes, n)
1019			}
1020		}
1021		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
1022	
1023		switch {
1024		case !sh.Closed:
1025			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
1026			rep.Items = currentItemsOfShift(d, sh.ID)
1027		case sh.CloseRecord != nil:
1028			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
1029			rep.ItemsAtClose = true
1030			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
1031			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
1032			for _, s := range rep.CloseItems {
1033				if it, _ := findItem(d, s.ItemID); it != nil {
1034					rep.LatestItems[s.ItemID] = *it
1035				}
1036			}
1037		default:
1038			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
1039			rep.HistoryIncomplete = true
1040			rep.Items = currentItemsOfShift(d, sh.ID)
1041		}
1042		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
1043	
1044		for i := range d.Handovers {
1045			h := &d.Handovers[i]
1046			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
1047			if !involved {
1048				continue
1049			}
1050			if h.FromShiftID == sh.ID {
1051				cp := *h
1052				rep.Outgoing = &cp
1053			}
1054			if h.ToShiftID == sh.ID {
1055				rep.Incoming = append(rep.Incoming, *h)
1056			}
1057			for j := range h.Entries {
1058				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
1059					HandoverID: h.ID,
1060					FromShift:  h.FromShiftID,
1061					ToShift:    h.ToShiftID,
1062					Entry:      h.Entries[j],
1063				})
1064			}
1065		}
1066		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
1067		for k := range rep.Results {
1068			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
1069		}
1070		return rep, nil
1071	}
1072

